import { test } from 'node:test';
import assert from 'node:assert/strict';
import { montarPerfil, criarChaveDinamica, adicionarCampo } from './solution.mjs';

test('montarPerfil cria o objeto com as três propriedades', () => {
  assert.deepEqual(montarPerfil('Ana', 15, 'São Paulo'), { nome: 'Ana', idade: 15, cidade: 'São Paulo' });
});

test('criarChaveDinamica usa o texto da variável como nome da chave', () => {
  assert.deepEqual(criarChaveDinamica('telefone', '(11) 9999-0000'), { telefone: '(11) 9999-0000' });
});

test('criarChaveDinamica funciona com outro nome de chave', () => {
  assert.deepEqual(criarChaveDinamica('email', 'ana@escola.com'), { email: 'ana@escola.com' });
});

test('adicionarCampo adiciona um campo novo ao perfil', () => {
  const perfil = montarPerfil('Ana', 15, 'São Paulo');
  adicionarCampo(perfil, 'telefone', '(11) 9999-0000');
  assert.equal(perfil.telefone, '(11) 9999-0000');
  assert.equal(perfil.nome, 'Ana');
});

solutionCode:
export function montarPerfil(nome, idade, cidade) {
  return { nome, idade, cidade };
}

export function criarChaveDinamica(nomeDaChave, valor) {
  return { [nomeDaChave]: valor };
}

export function adicionarCampo(perfil, nomeDoCampo, valor) {
  perfil[nomeDoCampo] = valor;
  return perfil;
}
